#include <cstdio>
#include <cmath>
using namespace std;

double a[20];

double cal1(double x, double y, double z)
{
    return z * log(y) + log(log(x));
}

double cal2(double x, double y, double z)
{
    return log(y * z * log(x));
}

int solve(double x, double y, double z)
{
    a[1] = cal1(x, y, z);
    a[2] = cal1(x, z, y);
    a[3] = cal2(x, y, z);
    a[4] = cal2(x, z, y);

    a[5] = cal1(y, x, z);
    a[6] = cal1(y, z, x);
    a[7] = cal2(y, x, z);
    a[8] = cal2(y, z, x);

    a[9] = cal1(z, x, y);
    a[10] = cal1(z, y, x);
    a[11] = cal2(z, x, y);
    a[12] = cal2(z, y, x);

    int result = 1;
    double maximum = a[1];

    for (int i = 2; i <= 12; ++i) {
        if (a[i] > maximum) {
            maximum = a[i];
            result = i;
        }
    }

    return result;
}

void print(int mark)
{
    static const char* expressions[] = {
        "",
        "x^y^z",
        "x^z^y",
        "(x^y)^z",
        "(x^z)^y",
        "y^x^z",
        "y^z^x",
        "(y^x)^z",
        "(y^z)^x",
        "z^x^y",
        "z^y^x",
        "(z^x)^y",
        "(z^y)^x"
    };

    printf("%s\n", expressions[mark]);
}

int main()
{
    double x, y, z;

    while (scanf("%lf%lf%lf", &x, &y, &z) == 3) {
        print(solve(x, y, z));
    }

    return 0;
}

